-- Pure scope calculations: no Auth simulation, DML, fixtures or business changes.
do $$
declare p_changes jsonb; mapped jsonb:='{}'; affected_yarn text[]; affected_greige text[]; changed_knit text[]; changed_dyed text[]; changed_program text[];
begin
 p_changes:='[{"table":"yarn_purchase_order_item","id":"1","before":{"quantity":2000},"values":{"quantity":6000}}]'::jsonb;
 select coalesce(array_agg(distinct ref) filter(where ref is not null),array[]::text[]) into affected_yarn from (select coalesce(mapped->>(c->>'id'),c->>'id') ref from jsonb_array_elements(p_changes) c where c->>'table'='yarn_bill_item' and c->'values'<>'null'::jsonb and exists(select 1 from unnest(array['billed_quantity']) f where c->'before'->f is distinct from c->'values'->f) union all select coalesce(mapped->>(v->>'yarn_bill_item_id'),v->>'yarn_bill_item_id') ref from jsonb_array_elements(p_changes) c cross join lateral (values(c->'before'),(c->'values')) x(v) where c->>'table'='knitting_bill_item' and c->'values'<>'null'::jsonb and exists(select 1 from unnest(array['consumption','yarn_bill_item_id']) f where c->'before'->f is distinct from c->'values'->f)) q;
 select coalesce(array_agg(distinct ref) filter(where ref is not null),array[]::text[]) into affected_greige from (select coalesce(mapped->>(c->>'id'),c->>'id') ref from jsonb_array_elements(p_changes) c where c->>'table'='knitting_bill_item' and c->'values'<>'null'::jsonb and exists(select 1 from unnest(array['billed_quantity']) f where c->'before'->f is distinct from c->'values'->f) union all select coalesce(mapped->>(v->>'knitting_bill_item_id'),v->>'knitting_bill_item_id') ref from jsonb_array_elements(p_changes) c cross join lateral (values(c->'before'),(c->'values')) x(v) where c->>'table'='dyed_fabric_item' and c->'values'<>'null'::jsonb and exists(select 1 from unnest(array['gross_quantity','knitting_bill_item_id']) f where c->'before'->f is distinct from c->'values'->f)) q;
 select coalesce(array_agg(distinct ref) filter(where ref is not null),array[]::text[]) into changed_knit from (select coalesce(mapped->>(c->>'id'),c->>'id') ref from jsonb_array_elements(p_changes) c where c->>'table'='knitting_bill_item' and c->'values'<>'null'::jsonb and exists(select 1 from unnest(array['billed_quantity','consumption']) f where c->'before'->f is distinct from c->'values'->f)) q;
 select coalesce(array_agg(distinct ref) filter(where ref is not null),array[]::text[]) into changed_dyed from (select coalesce(mapped->>(c->>'id'),c->>'id') ref from jsonb_array_elements(p_changes) c where c->>'table'='dyed_fabric_item' and c->'values'<>'null'::jsonb and exists(select 1 from unnest(array['billed_quantity','gross_quantity','final_quantity','knitting_bill_item_id','dyeing_program_item_id']) f where c->'before'->f is distinct from c->'values'->f)) q;
 select coalesce(array_agg(distinct ref) filter(where ref is not null),array[]::text[]) into changed_program from (select coalesce(mapped->>(c->>'id'),c->>'id') ref from jsonb_array_elements(p_changes) c where c->>'table'='dyeing_program_item' and c->'values'<>'null'::jsonb and exists(select 1 from unnest(array['fabric_type_id']) f where c->'before'->f is distinct from c->'values'->f)) q;
 if cardinality(affected_yarn)+cardinality(affected_greige)+cardinality(changed_knit)+cardinality(changed_dyed)+cardinality(changed_program)<>0 then raise exception 'A purchase order wrongly triggers production balance checks';end if;
 p_changes:='[{"table":"knitting_bill_item","id":"1","before":{"billed_quantity":1000,"consumption":997.92,"yarn_bill_item_id":"2"},"values":{"billed_quantity":1000,"consumption":998,"yarn_bill_item_id":"2"}}]'::jsonb;
 select coalesce(array_agg(distinct ref) filter(where ref is not null),array[]::text[]) into affected_yarn from (select coalesce(mapped->>(c->>'id'),c->>'id') ref from jsonb_array_elements(p_changes) c where c->>'table'='yarn_bill_item' and c->'values'<>'null'::jsonb and exists(select 1 from unnest(array['billed_quantity']) f where c->'before'->f is distinct from c->'values'->f) union all select coalesce(mapped->>(v->>'yarn_bill_item_id'),v->>'yarn_bill_item_id') ref from jsonb_array_elements(p_changes) c cross join lateral (values(c->'before'),(c->'values')) x(v) where c->>'table'='knitting_bill_item' and c->'values'<>'null'::jsonb and exists(select 1 from unnest(array['consumption','yarn_bill_item_id']) f where c->'before'->f is distinct from c->'values'->f)) q;
 select coalesce(array_agg(distinct ref) filter(where ref is not null),array[]::text[]) into affected_greige from (select coalesce(mapped->>(c->>'id'),c->>'id') ref from jsonb_array_elements(p_changes) c where c->>'table'='knitting_bill_item' and c->'values'<>'null'::jsonb and exists(select 1 from unnest(array['billed_quantity']) f where c->'before'->f is distinct from c->'values'->f) union all select coalesce(mapped->>(v->>'knitting_bill_item_id'),v->>'knitting_bill_item_id') ref from jsonb_array_elements(p_changes) c cross join lateral (values(c->'before'),(c->'values')) x(v) where c->>'table'='dyed_fabric_item' and c->'values'<>'null'::jsonb and exists(select 1 from unnest(array['gross_quantity','knitting_bill_item_id']) f where c->'before'->f is distinct from c->'values'->f)) q;
 select coalesce(array_agg(distinct ref) filter(where ref is not null),array[]::text[]) into changed_knit from (select coalesce(mapped->>(c->>'id'),c->>'id') ref from jsonb_array_elements(p_changes) c where c->>'table'='knitting_bill_item' and c->'values'<>'null'::jsonb and exists(select 1 from unnest(array['billed_quantity','consumption']) f where c->'before'->f is distinct from c->'values'->f)) q;
 select coalesce(array_agg(distinct ref) filter(where ref is not null),array[]::text[]) into changed_dyed from (select coalesce(mapped->>(c->>'id'),c->>'id') ref from jsonb_array_elements(p_changes) c where c->>'table'='dyed_fabric_item' and c->'values'<>'null'::jsonb and exists(select 1 from unnest(array['billed_quantity','gross_quantity','final_quantity','knitting_bill_item_id','dyeing_program_item_id']) f where c->'before'->f is distinct from c->'values'->f)) q;
 select coalesce(array_agg(distinct ref) filter(where ref is not null),array[]::text[]) into changed_program from (select coalesce(mapped->>(c->>'id'),c->>'id') ref from jsonb_array_elements(p_changes) c where c->>'table'='dyeing_program_item' and c->'values'<>'null'::jsonb and exists(select 1 from unnest(array['fabric_type_id']) f where c->'before'->f is distinct from c->'values'->f)) q;
 if changed_knit<>array['1'] or affected_yarn<>array['2'] or cardinality(affected_greige)<>0 then raise exception 'Knitting validation did not target exactly its changed line and yarn source';end if;
 p_changes:='[{"table":"knitting_bill_item","id":"1","before":{"billed_quantity":1000,"consumption":997.92,"greige_gsm":180},"values":{"billed_quantity":1000,"consumption":997.92,"greige_gsm":190}}]'::jsonb;
 select coalesce(array_agg(distinct ref) filter(where ref is not null),array[]::text[]) into affected_yarn from (select coalesce(mapped->>(c->>'id'),c->>'id') ref from jsonb_array_elements(p_changes) c where c->>'table'='yarn_bill_item' and c->'values'<>'null'::jsonb and exists(select 1 from unnest(array['billed_quantity']) f where c->'before'->f is distinct from c->'values'->f) union all select coalesce(mapped->>(v->>'yarn_bill_item_id'),v->>'yarn_bill_item_id') ref from jsonb_array_elements(p_changes) c cross join lateral (values(c->'before'),(c->'values')) x(v) where c->>'table'='knitting_bill_item' and c->'values'<>'null'::jsonb and exists(select 1 from unnest(array['consumption','yarn_bill_item_id']) f where c->'before'->f is distinct from c->'values'->f)) q;
 select coalesce(array_agg(distinct ref) filter(where ref is not null),array[]::text[]) into affected_greige from (select coalesce(mapped->>(c->>'id'),c->>'id') ref from jsonb_array_elements(p_changes) c where c->>'table'='knitting_bill_item' and c->'values'<>'null'::jsonb and exists(select 1 from unnest(array['billed_quantity']) f where c->'before'->f is distinct from c->'values'->f) union all select coalesce(mapped->>(v->>'knitting_bill_item_id'),v->>'knitting_bill_item_id') ref from jsonb_array_elements(p_changes) c cross join lateral (values(c->'before'),(c->'values')) x(v) where c->>'table'='dyed_fabric_item' and c->'values'<>'null'::jsonb and exists(select 1 from unnest(array['gross_quantity','knitting_bill_item_id']) f where c->'before'->f is distinct from c->'values'->f)) q;
 select coalesce(array_agg(distinct ref) filter(where ref is not null),array[]::text[]) into changed_knit from (select coalesce(mapped->>(c->>'id'),c->>'id') ref from jsonb_array_elements(p_changes) c where c->>'table'='knitting_bill_item' and c->'values'<>'null'::jsonb and exists(select 1 from unnest(array['billed_quantity','consumption']) f where c->'before'->f is distinct from c->'values'->f)) q;
 select coalesce(array_agg(distinct ref) filter(where ref is not null),array[]::text[]) into changed_dyed from (select coalesce(mapped->>(c->>'id'),c->>'id') ref from jsonb_array_elements(p_changes) c where c->>'table'='dyed_fabric_item' and c->'values'<>'null'::jsonb and exists(select 1 from unnest(array['billed_quantity','gross_quantity','final_quantity','knitting_bill_item_id','dyeing_program_item_id']) f where c->'before'->f is distinct from c->'values'->f)) q;
 select coalesce(array_agg(distinct ref) filter(where ref is not null),array[]::text[]) into changed_program from (select coalesce(mapped->>(c->>'id'),c->>'id') ref from jsonb_array_elements(p_changes) c where c->>'table'='dyeing_program_item' and c->'values'<>'null'::jsonb and exists(select 1 from unnest(array['fabric_type_id']) f where c->'before'->f is distinct from c->'values'->f)) q;
 if cardinality(changed_knit)+cardinality(affected_yarn)+cardinality(affected_greige)<>0 then raise exception 'A non-quantity edit wrongly revalidates historical yields';end if;
end $$;
